import React from 'react';
import './HeroSection.css';
import { Link } from 'react-router-dom';

const HeroSection = () => {
  return (
    <section className="hero-section">
      <div className="hero-left">
        <h1>
          Welcome to <span className="highlight">MediVault Pro</span>
        </h1>
        <p>Your trusted digital vault for all your medical records.</p>
        <Link to="/register" className="hero-button">
          Get Started
        </Link>
      </div>
      <div className="hero-right">
        <img
          src="https://cdn.pixabay.com/photo/2017/08/06/00/05/stethoscope-2587635_1280.jpg"
          alt="Medical Illustration"
        />
      </div>
    </section>
  );
};

export default HeroSection;
